     1	import { z } from "zod";
     2	import type { NotificationKind } from "@/types/notification";
     3	import {
     4	  notificationIdSchema,
     5	  orgIdSchema,
     6	  pageRequestSchema,
     7	  userIdSchema,
     8	} from "./common";
     9	
    10	export const notificationKindSchema = z.enum([
    11	  "issue_assigned",
    12	  "issue_status_changed",
    13	  "issue_due_soon",
    14	  "issue_overdue",
    15	  "comment_created",
    16	  "comment_mention",
    17	  "member_invited",
    18	  "member_joined",
    19	  "project_archived",
    20	  "plan_limit_reached",
    21	  "digest_ready",
    22	]);
    23	
    24	export const notificationChannelSchema = z.enum(["in_app", "email", "webhook"]);
    25	
    26	export const markNotificationReadSchema = z.object({
    27	  orgId: orgIdSchema,
    28	  notificationId: notificationIdSchema,
    29	});
    30	
    31	export const markAllNotificationsReadSchema = z.object({
    32	  orgId: orgIdSchema,
    33	});
    34	
    35	export const listNotificationsSchema = z
    36	  .object({
    37	    orgId: orgIdSchema,
    38	    recipientId: userIdSchema,
    39	    unreadOnly: z.boolean().default(false),
    40	    kind: z.array(notificationKindSchema).optional(),
    41	  })
    42	  .extend(pageRequestSchema.shape);
    43	
    44	export const updateNotificationPreferenceSchema = z.object({
    45	  orgId: orgIdSchema,
    46	  userId: userIdSchema,
    47	  kind: notificationKindSchema,
    48	  inApp: z.boolean(),
    49	  email: z.boolean(),
    50	  digestOnly: z.boolean(),
    51	});
    52	
    53	const _kindParity: NotificationKind = "comment_mention" satisfies z.infer<
    54	  typeof notificationKindSchema
    55	>;
    56	void _kindParity;
    57	
    58	export type MarkNotificationReadInput = z.infer<
    59	  typeof markNotificationReadSchema
    60	>;
    61	export type ListNotificationsInput = z.infer<typeof listNotificationsSchema>;
    62	export type UpdateNotificationPreferenceInput = z.infer<
    63	  typeof updateNotificationPreferenceSchema
    64	>;

